import { useEffect, useMemo, useRef, useState } from 'react';
import { Activity, Archive, ArrowLeft, Bell, Check, ClipboardCheck, Crown, Edit3, Globe2, Home, Image, KeyRound, Lock, Menu, MessageCircle, Plus, Recycle, RefreshCw, ScrollText, Settings2, Share2, ShieldCheck, Trash2, Trophy, UserCog, UserPlus, Users, X } from 'lucide-react';
import { db } from '../lib/cloudflare';
import { RecentItems } from './RecentItems';

const TABS = [
  ['overview', 'Overview', Activity], ['applications', 'Applications', ClipboardCheck], ['members', 'Members', Users],
  ['roles', 'Role Management', ShieldCheck], ['permissions', 'Permissions', ShieldCheck], ['website', 'Website Admins', UserCog], ['codenames', 'Codenames', KeyRound],
  ['sharing', 'Document Sharing', Share2], ['community', 'Community Control', Globe2], ['media', 'Media Management', Image], ['scores', 'Calcitonins', Trophy], ['notifications', 'Notifications', Bell],
  ['audit', 'Audit Logs', ScrollText], ['recycle', 'Recycle Bin', Recycle], ['settings', 'Settings', Settings2],
] as const;
type Tab = typeof TABS[number][0];
const actions = ['View', 'Create', 'Edit', 'Delete', 'Manage'] as const;

export const PhantomControlCenter = ({
  onOpenVault,
  onBack,
  onHome,
  onOpenCommunity,
}: {
  onOpenVault: () => void;
  onBack?: () => void;
  onHome?: () => void;
  onOpenCommunity?: () => void;
}) => {
  const [tab, setTab] = useState<Tab>('overview');
  const [navigationOpen, setNavigationOpen] = useState(() => window.innerWidth >= 1024);
  const [overview, setOverview] = useState<any>(null);
  const [applications, setApplications] = useState<any[]>([]);
  const [members, setMembers] = useState<any[]>([]);
  const [roleData, setRoleData] = useState<any>({ roles: [], permissions: [], sections: [] });
  const [websiteAdmins, setWebsiteAdmins] = useState<any>({ admins: [], permissions: [], availablePermissions: [] });
  const [codenameData, setCodenameData] = useState<any>({ codenames: [], history: [] });
  const [auditLogs, setAuditLogs] = useState<any[]>([]);
  const [recycleItems, setRecycleItems] = useState<any[]>([]);
  const [settings, setSettings] = useState<any[]>([]);
  const [vaultSections, setVaultSections] = useState<any[]>([]);
  const [sharingData, setSharingData] = useState<any>({ globalEnabled: false, permissions: [] });
  const [communityMedia, setCommunityMedia] = useState<any>({ settings: [], totals: { fileCount: 0, storageBytes: 0 }, byType: [] });
  const [communityGroups, setCommunityGroups] = useState<any[]>([]);
  const [communityReports, setCommunityReports] = useState<any[]>([]);
  const [scoreRules, setScoreRules] = useState<any[]>([]);
  const [notificationDelegates, setNotificationDelegates] = useState<any[]>([]);
  const [sentNotifications, setSentNotifications] = useState<any[]>([]);
  const [initialLoading, setInitialLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [createForApplication, setCreateForApplication] = useState<any | null>(null);
  const [showCreateMember, setShowCreateMember] = useState(false);
  const [historyMember, setHistoryMember] = useState<any | null>(null);
  const [activationInvite, setActivationInvite] = useState<any | null>(null);
  const loadedTabs = useRef<Set<Tab>>(new Set());

  const load = async (target = tab, background = false) => {
    const firstLoad = !loadedTabs.current.has(target);
    if (firstLoad && !background) setInitialLoading(true);
    else setRefreshing(true);
    try {
      if (target === 'overview') setOverview(await db.phantom.overview());
      if (target === 'applications') { setApplications(await db.phantom.applications()); setRoleData(await db.phantom.roles()); }
      if (target === 'members') { setMembers(await db.phantom.members()); setRoleData(await db.phantom.roles()); }
      if (target === 'roles') setRoleData(await db.phantom.roles());
      if (target === 'permissions') { setRoleData(await db.phantom.roles()); setMembers(await db.phantom.members()); }
      if (target === 'website') { setWebsiteAdmins(await db.phantom.websiteAdmins()); if (!members.length) setMembers(await db.phantom.members('active')); }
      if (target === 'codenames') { setCodenameData(await db.phantom.codenames()); if (!members.length) setMembers(await db.phantom.members()); }
      if (target === 'sharing') { const [sharing, memberRows] = await Promise.all([db.phantom.sharing(), db.phantom.members()]); setSharingData(sharing); setMembers(memberRows); }
      if (target === 'community') { const [groups, reports, memberRows] = await Promise.all([db.community.groups(), db.communityAdmin.publicReports(), db.phantom.members('active')]); setCommunityGroups(groups); setCommunityReports(reports); setMembers(memberRows); }
      if (target === 'media') setCommunityMedia(await db.communityAdmin.mediaSettings());
      if (target === 'scores') { const [rules, memberRows] = await Promise.all([db.phantom.scoreRules(), db.phantom.members()]); setScoreRules(rules); setMembers(memberRows); }
      if (target === 'notifications') { const [delegates, memberRows, roles, sent] = await Promise.all([db.phantom.notificationDelegates(), db.phantom.members('active'), db.phantom.roles(), db.notifications.sent()]); setNotificationDelegates(delegates); setMembers(memberRows); setRoleData(roles); setSentNotifications(sent); }
      if (target === 'audit') setAuditLogs(await db.phantom.auditLogs());
      if (target === 'recycle') setRecycleItems(await db.phantom.recycleBin());
      if (target === 'settings') { setSettings(await db.phantom.settings()); setVaultSections(await db.phantom.vaultSections()); }
      loadedTabs.current.add(target);
    } catch (error: any) {
      setMessage(error?.message || 'PHANTOM Control Center could not load this data.');
    } finally {
      setInitialLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => { void load(tab); }, [tab]);

  const refresh = async () => { await load(tab, true); setMessage('Saved and refreshed in the background.'); };
  const refreshTab = async (target: Tab, confirmation = 'Saved.') => { await load(target, true); setMessage(confirmation); };
  const openCreate = (application?: any) => { setCreateForApplication(application || null); setShowCreateMember(true); };
  const regenerateActivation = async (profileId: number) => {
    try {
      const result = await db.phantom.regenerateActivationLink(profileId);
      setActivationInvite(result.data);
      await refreshTab(tab === 'applications' ? 'applications' : 'members', result.message || 'A replacement password-setup invitation is ready.');
    } catch (error: any) { setMessage(error?.message || 'Could not generate a replacement password-setup invitation.'); }
  };

  return <div className="min-h-screen bg-[#f7faf8]">
    <header className="sticky top-0 z-40 border-b border-emerald-100 bg-white/95 px-4 py-3 backdrop-blur sm:px-7">
      <div className="mx-auto flex max-w-[1600px] items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-2 sm:gap-3">
          <button onClick={() => setNavigationOpen((current) => !current)} className="rounded-xl border border-emerald-200 bg-emerald-50 p-2.5 text-emerald-800 hover:bg-emerald-100" aria-label={navigationOpen ? 'Hide PHANTOM navigation' : 'Show PHANTOM navigation'}><Menu className="h-5 w-5" /></button>
          {onBack && <button onClick={onBack} className="inline-flex shrink-0 items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-2.5 py-2 text-xs font-black text-slate-600 hover:bg-slate-50"><ArrowLeft className="h-4 w-4" /><span className="hidden sm:inline">Back</span></button>}
          {(onHome || onBack) && <button onClick={onHome || onBack} className="inline-flex shrink-0 items-center gap-1.5 rounded-xl border border-emerald-200 bg-emerald-50 px-2.5 py-2 text-xs font-black text-emerald-800 hover:bg-emerald-100" title="Admin home"><Home className="h-4 w-4" /><span className="hidden md:inline">Home</span></button>}
          <img src="/logo.png" alt="Code Rx Society" className="h-10 w-10 shrink-0 object-contain" />
          <div className="min-w-0"><p className="truncate text-sm font-black tracking-wide text-slate-900">PHANTOM CONTROL</p><p className="truncate text-[9px] font-black uppercase tracking-[0.16em] text-emerald-700">Wide founder workspace</p></div>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {onOpenCommunity && <button onClick={onOpenCommunity} className="inline-flex items-center gap-1.5 rounded-xl border border-emerald-200 bg-emerald-50 px-2.5 py-2 text-xs font-black text-emerald-800 hover:bg-emerald-100" title="Open Code Rx Community"><MessageCircle className="h-4 w-4" /><span className="hidden sm:inline">Community</span></button>}
          <button onClick={() => void refresh()} disabled={refreshing} className="inline-flex items-center gap-2 rounded-xl border border-emerald-200 bg-white px-3 py-2.5 text-xs font-black uppercase tracking-wider text-emerald-800 hover:bg-emerald-50 disabled:opacity-60"><RefreshCw className="h-4 w-4" /><span className="hidden sm:inline">{refreshing ? 'Refreshing…' : 'Refresh'}</span></button>
        </div>
      </div>
    </header><div className="mx-auto max-w-[1600px] space-y-6 px-4 py-6 sm:px-7 lg:px-10"><div className="relative overflow-hidden rounded-3xl border border-emerald-100 bg-gradient-to-br from-[#fbfffc] via-[#eefaf2] to-[#dff5e7] p-7 text-slate-800 shadow-lg shadow-emerald-950/5 sm:p-9"><div className="absolute -right-20 -top-24 h-72 w-72 rounded-full bg-emerald-300/25 blur-3xl" /><div className="relative flex flex-wrap items-start justify-between gap-5"><div><p className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.24em] text-emerald-700"><Crown className="h-3.5 w-3.5" /> Founder-level administration</p><h2 className="mt-3 text-3xl font-black tracking-tight text-slate-800 sm:text-4xl">PHANTOM CONTROL CENTER</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-600">Organization-wide membership, permissions, website delegation, codename ballot, Vault records, notifications, and protected activity history.</p></div></div></div>
    {message && <div role="status" className="flex items-start justify-between gap-3 rounded-2xl border border-emerald-100 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700"><span>{message}</span><button onClick={() => setMessage(null)}><X className="h-4 w-4" /></button></div>}
    <div className={`grid gap-6 ${navigationOpen ? 'lg:grid-cols-[235px_minmax(0,1fr)]' : 'lg:grid-cols-1'}`}>{navigationOpen && <aside className="h-fit rounded-2xl border border-slate-100 bg-white p-3 shadow-sm"><div className="flex items-center justify-between px-3 py-2"><p className="text-[10px] font-black uppercase tracking-[0.18em] text-slate-400">Founder controls</p><button onClick={() => setNavigationOpen(false)} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></div>{TABS.map(([id, label, Icon]) => <button key={id} onClick={() => { setTab(id); if (window.innerWidth < 1024) setNavigationOpen(false); }} className={`mt-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold transition ${tab === id ? 'border border-emerald-200 bg-emerald-50 text-emerald-800 shadow-sm shadow-emerald-100' : 'text-slate-600 hover:bg-slate-50 hover:text-emerald-700'}`}><Icon className="h-4 w-4" />{label}</button>)}</aside>}
      <main className="min-w-0 rounded-2xl border border-slate-100 bg-white p-5 shadow-sm sm:p-7">{initialLoading ? <div className="grid min-h-64 place-items-center"><p className="rounded-xl border border-emerald-100 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-700">Opening PHANTOM controls…</p></div> : <><div className="mb-4 min-h-5 text-xs font-bold text-emerald-700" aria-live="polite">{refreshing ? 'Saving and refreshing in the background…' : ''}</div>{tab === 'overview' && <Overview data={overview} onTab={setTab} onCreate={() => openCreate()} onOpenVault={onOpenVault} />}{tab === 'applications' && <Applications applications={applications} onCreate={openCreate} onReview={async (id, status) => { try { await db.phantom.reviewApplication(id, status); await refreshTab('applications', status === 'rejected' ? 'Application rejected.' : 'Application returned to pending review.'); } catch (error: any) { setMessage(error?.message || 'Could not update this application.'); } }} onRegenerateActivation={regenerateActivation} onRemove={async (application) => { try { await db.applications.remove(application.id); await refreshTab('applications', 'Application deleted.'); } catch (error: any) { setMessage(error?.message || 'Could not delete this application.'); } }} />}{tab === 'members' && <Members members={members} roles={roleData.roles || []} onCreate={() => openCreate()} onHistory={setHistoryMember} onRegenerateActivation={regenerateActivation} onUpdate={async (id, data) => { try { await db.phantom.updateMember(id, data); await refreshTab('members'); } catch (error: any) { setMessage(error?.message || 'Could not update this member.'); } }} onSetCalcitonins={async (id, value, reason) => { try { await db.phantom.adjustScore(id, { action: 'set', points: value, reason }); await refreshTab('members', 'Calcitonin balance saved.'); } catch (error: any) { setMessage(error?.message || 'Could not update this Calcitonin balance.'); } }} />}{tab === 'roles' && <Roles data={roleData} onSaved={() => { void refreshTab('roles'); }} />}{tab === 'permissions' && <MemberPermissions members={members} sections={roleData.sections || []} onSaved={() => { setMessage('Permissions saved.'); }} />}{tab === 'website' && <WebsiteAdmins data={websiteAdmins} members={members} onSaved={() => { void refreshTab('website'); }} />}{tab === 'codenames' && <Codenames data={codenameData} members={members} onSaved={() => { void refreshTab('codenames'); }} />}{tab === 'audit' && <AuditLog logs={auditLogs} />}{tab === 'recycle' && <RecycleBin items={recycleItems} onChanged={() => { void refreshTab('recycle'); }} />}{tab === 'sharing' && <SharingControl data={sharingData} members={members} onSaved={() => { void refreshTab('sharing'); }} />}{tab === 'community' && <CommunityAdministration groups={communityGroups} reports={communityReports} members={members} onSaved={() => { void refreshTab('community'); }} />}{tab === 'media' && <CommunityMediaManagement data={communityMedia} onSaved={() => { void refreshTab('media'); }} />}{tab === 'scores' && <ScoreSystem rules={scoreRules} members={members} onSaved={() => { void refreshTab('scores'); }} />}{tab === 'notifications' && <NotificationAdministration delegates={notificationDelegates} members={members} roles={roleData.roles || []} sentNotifications={sentNotifications} onSaved={() => { void refreshTab('notifications'); }} />}{tab === 'settings' && <Settings settings={settings} sections={vaultSections} onSaved={() => { void refreshTab('settings'); }} />}</>}</main></div>
    {showCreateMember && <CreateMemberModal application={createForApplication} roles={roleData.roles || []} onClose={() => setShowCreateMember(false)} onCreated={async () => { setShowCreateMember(false); await refreshTab(createForApplication ? 'applications' : 'members', 'Secure member invitation created.'); }} />}
    {activationInvite && <ActivationInviteDialog invitation={activationInvite} onClose={() => setActivationInvite(null)} />}
    {historyMember && <MemberHistory member={historyMember} onClose={() => setHistoryMember(null)} />}</div></div>;
};

const Overview = ({ data, onTab, onCreate, onOpenVault }: { data: any; onTab: (tab: Tab) => void; onCreate: () => void; onOpenVault: () => void }) => {
  const stats: Array<[string, string | number, string]> = [
    ['Members', data?.activeMembers ?? '—', 'members'],
    ['Pending applications', data?.pendingApplications ?? '—', 'applications'],
    ['Website admins', data?.websiteAdmins ?? '—', 'website'],
    ['Vault documents', data?.vaultDocuments ?? '—', 'vault'],
    ['Draft documents', data?.draftDocuments ?? '—', 'vault'],
    ['In review', data?.reviewDocuments ?? '—', 'vault'],
    ['Projects', data?.projects ?? '—', 'vault'],
    ['Vault storage', data?.vaultStorageBytes ? `${(data.vaultStorageBytes / 1024 / 1024).toFixed(2)} MB` : '0 MB', 'vault'],
    ['Archived members', data?.archivedMembers ?? '—', 'members'],
  ];
  const shortcuts: Array<[string, string]> = [
    ['Review Applications', 'applications'], ['Manage Members', 'members'], ['Calcitonins', 'scores'], ['Document Sharing', 'sharing'], ['Notifications', 'notifications'], ['Manage Roles', 'roles'], ['Manage Permissions', 'permissions'], ['Manage Codenames', 'codenames'], ['Website Administrators', 'website'], ['Audit Logs', 'audit'], ['Recycle Bin', 'recycle'], ['System Settings', 'settings'],
  ];
  const activity = data?.recentActivity || [];

  return <div>
    <div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-emerald-600">Organization status</p><h3 className="mt-1 text-2xl font-black text-slate-900">Founder overview</h3></div><button onClick={onCreate} className="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase tracking-wider text-white"><UserPlus className="h-4 w-4" />Create member</button></div>
    <div className="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{stats.map(([label, value, target]) => <button key={label} onClick={() => target === 'vault' ? onOpenVault() : onTab(target as Tab)} className="rounded-2xl border border-slate-100 bg-slate-50 p-5 text-left transition hover:border-emerald-200 hover:bg-emerald-50"><p className="text-[10px] font-black uppercase tracking-wider text-slate-400">{label}</p><p className="mt-2 text-3xl font-black text-slate-900">{value}</p></button>)}</div>
    <div className="mt-6 flex flex-wrap gap-2"><button onClick={onOpenVault} className="mini-button !border-emerald-200 !bg-emerald-50 !text-emerald-700">Open Vault</button>{shortcuts.map(([label, target]) => <button key={label} onClick={() => onTab(target as Tab)} className="mini-button text-emerald-700">{label}</button>)}</div>
    <section className="mt-7"><div className="flex items-baseline justify-between gap-3"><h4 className="text-lg font-black text-slate-900">Recent activity</h4><span className="text-xs font-bold text-slate-400">Latest 3 first</span></div><div className="mt-3 space-y-2">{activity.length ? <RecentItems items={activity} label="activity entries" render={(item) => <div key={item.id} className="rounded-xl border border-slate-100 px-4 py-3"><p className="text-sm font-bold text-slate-800">{String(item.action || '').replace(/\./g, ' ')}</p><p className="mt-1 text-xs text-slate-500">{item.actor_name || 'System'} · {item.created_at}</p></div>} /> : <p className="text-sm text-slate-500">Administrative actions will appear here.</p>}</div></section>
  </div>;
};

const Applications = ({
  applications,
  onCreate,
  onReview,
  onRegenerateActivation,
  onRemove,
}: {
  applications: any[];
  onCreate: (application: any) => void;
  onReview: (id: number, status: 'rejected' | 'pending') => void;
  onRegenerateActivation: (profileId: number) => void;
  onRemove: (application: any) => void;
}) => {
  const invitationState = (application: any) => {
    if (!application.member_profile_id) return application.status === 'approved' ? 'Invitation incomplete' : application.status === 'rejected' ? 'Rejected' : 'Pending PHANTOM approval';
    if (application.member_status === 'active') return 'Member active';
    if (application.member_status !== 'pending_activation') return application.member_status?.replace(/_/g, ' ') || 'Member linked';
    const expiry = application.activation_expires_at ? new Date(application.activation_expires_at).getTime() : 0;
    if (expiry && expiry < Date.now()) return 'Password setup link expired';
    return application.activation_delivery_status === 'sent' ? 'Password setup email sent' : 'Password setup link ready';
  };
  const formattedExpiry = (value?: string) => value ? new Date(value).toLocaleString(undefined, { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';

  return <div>
    <Header eyebrow="Membership intake" title="JOIN applications & secure invitations" />
    <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">One approval creates the member record, permanent member ID, and a one-time password-setup invitation. Applicants never choose a password until PHANTOM has approved them.</p>
    <div className="mt-5 space-y-3">{applications.map((application) => {
      const awaitingActivation = Boolean(application.member_profile_id) && application.member_status === 'pending_activation';
      const canInvite = !application.member_profile_id && application.status !== 'rejected';
      return <article key={application.id} className="rounded-2xl border border-slate-100 p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div className="min-w-0"><p className="font-black text-slate-900">{application.name}</p><p className="mt-1 break-all text-sm text-slate-500">{application.email} · {application.phone || 'No phone provided'}</p><div className="mt-3 flex flex-wrap items-center gap-2"><Status status={application.member_status || application.status} /><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-slate-600">{invitationState(application)}</span>{application.member_code && <span className="rounded-full border border-emerald-100 bg-emerald-50 px-2.5 py-1 text-[10px] font-black uppercase tracking-wider text-emerald-700">{application.member_code}</span>}</div>{awaitingActivation && <p className="mt-3 text-xs font-bold text-amber-700">Password setup link expires: {formattedExpiry(application.activation_expires_at)} · {application.activation_delivery_status === 'sent' ? 'email sent' : 'manual secure delivery required'}</p>}{application.review_note && <p className="mt-3 max-w-2xl rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-600">PHANTOM note: {application.review_note}</p>}</div><div className="flex flex-wrap gap-2">{canInvite && <button onClick={() => onCreate(application)} className="mini-button bg-emerald-600 !text-white">{application.status === 'approved' ? 'Complete invitation' : 'Approve & invite'}</button>}{awaitingActivation && <button onClick={() => onRegenerateActivation(Number(application.member_profile_id))} className="mini-button border border-sky-200 bg-sky-50 !text-sky-800">Regenerate link</button>}{application.status === 'pending' && <button onClick={() => onReview(application.id, 'rejected')} className="mini-button text-red-600">Reject</button>}{application.status === 'rejected' && !application.member_profile_id && <button onClick={() => onReview(application.id, 'pending')} className="mini-button text-emerald-700">Return to pending</button>}{!application.member_profile_id && <button onClick={() => { if (window.confirm(`Delete the application from ${application.name}?`)) onRemove(application); }} className="mini-button text-red-600">Delete</button>}</div></div></article>;
    })}{!applications.length && <Empty label="No membership applications yet." />}</div>
  </div>;
};

const Members = ({ members, roles, onCreate, onHistory, onRegenerateActivation, onUpdate, onSetCalcitonins }: { members: any[]; roles: any[]; onCreate: () => void; onHistory: (member: any) => void; onRegenerateActivation: (profileId: number) => void; onUpdate: (id: number, data: any) => void | Promise<void>; onSetCalcitonins: (id: number, value: number, reason: string) => void | Promise<void> }) => {
  const assignableRoles = roles.filter((role) => role.code !== 'phantom');
  const [editingCalcitoninId, setEditingCalcitoninId] = useState<number | null>(null);
  const [calcitoninDraft, setCalcitoninDraft] = useState('');
  const saveCalcitonins = async (member: any) => {
    const value = Number(calcitoninDraft);
    if (!Number.isInteger(value) || value < 0 || value > 1_000_000) return;
    await onSetCalcitonins(member.id, value, 'Direct PHANTOM Calcitonin balance edit');
    setEditingCalcitoninId(null);
  };

  return <div>
    <div className="flex flex-wrap items-end justify-between gap-4"><Header eyebrow="Member management" title="Member records" /><button onClick={onCreate} className="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase text-white"><UserPlus className="h-4 w-4" />Create member</button></div>
    <p className="mt-2 text-sm text-slate-500">Click a member’s <strong className="text-emerald-700">CAL</strong> balance to set it directly. Every change is recorded in their Calcitonin history.</p>
    <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="border-b border-slate-100 text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="px-3 py-3">Member</th><th>Role</th><th>Identity</th><th>Calcitonins</th><th>Status</th><th className="text-right">Controls</th></tr></thead><tbody>{members.map((member) => {
      const isFounder = member.role_code === 'phantom';
      const editing = editingCalcitoninId === member.id;
      return <tr key={member.id} className="border-b border-slate-50"><td className="px-3 py-4"><p className="font-bold text-slate-900">{member.name}</p><p className="text-xs text-slate-500">{member.email}</p><p className="mt-1 text-[10px] font-black text-emerald-600">{member.member_code}</p></td><td>{isFounder ? <span className="inline-flex items-center gap-1.5 rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 text-xs font-black text-emerald-800"><Crown className="h-3.5 w-3.5 text-emerald-300" />PHANTOM</span> : <select value={member.role_code || 'member'} onChange={(event) => { void onUpdate(member.id, { roleCode: event.target.value }); }} className="rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-xs font-bold text-slate-700">{assignableRoles.map((role) => <option key={role.id} value={role.code}>{role.name}</option>)}</select>}</td><td className="text-sm font-bold text-slate-600">{member.codename || 'Awaiting codename'}</td><td>{isFounder ? <span className="text-sm font-black text-emerald-700">{Number(member.points || 0).toLocaleString()} CAL</span> : editing ? <div className="flex items-center gap-1"><input autoFocus type="number" min="0" max="1000000" value={calcitoninDraft} onChange={(event) => setCalcitoninDraft(event.target.value)} className="w-24 rounded-lg border border-emerald-200 px-2 py-1.5 text-sm font-black text-emerald-700" /><button onClick={() => void saveCalcitonins(member)} title="Save Calcitonins" className="rounded-lg p-1.5 text-emerald-700 hover:bg-emerald-50"><Check className="h-4 w-4" /></button><button onClick={() => setEditingCalcitoninId(null)} title="Cancel" className="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100"><X className="h-4 w-4" /></button></div> : <button onClick={() => { setEditingCalcitoninId(member.id); setCalcitoninDraft(String(Number(member.points || 0))); }} className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-50 px-2.5 py-1.5 text-sm font-black text-emerald-700 transition hover:bg-emerald-100" title="Set Calcitonin balance directly">{Number(member.points || 0).toLocaleString()} CAL<Edit3 className="h-3.5 w-3.5" /></button>}</td><td><Status status={member.status} /></td><td><div className="flex justify-end gap-1"><button onClick={() => onHistory(member)} className="icon-button" title="History"><ScrollText className="h-4 w-4" /></button>{isFounder ? <span className="inline-flex items-center px-2 text-[10px] font-black uppercase tracking-wider text-slate-400">Protected</span> : <>{member.status === 'pending_activation' && <button onClick={() => onRegenerateActivation(member.id)} className="icon-button text-sky-700" title="Generate a replacement password-setup link"><KeyRound className="h-4 w-4" /></button>}{member.status === 'active' && <button onClick={() => { void onUpdate(member.id, { action: 'lock' }); }} className="icon-button text-amber-600" title="Lock"><Lock className="h-4 w-4" /></button>}{member.status === 'locked' && <button onClick={() => { void onUpdate(member.id, { action: 'unlock' }); }} className="icon-button text-emerald-600" title="Unlock"><ShieldCheck className="h-4 w-4" /></button>}{member.status !== 'archived' && <button onClick={() => { void onUpdate(member.id, { action: 'archive' }); }} className="icon-button text-slate-500" title="Archive"><Archive className="h-4 w-4" /></button>}{member.status === 'archived' && <button onClick={() => { void onUpdate(member.id, { action: 'restore' }); }} className="icon-button text-emerald-600" title="Restore archived member"><RefreshCw className="h-4 w-4" /></button>}</>}</div></td></tr>;
    })}</tbody></table>{!members.length && <Empty label="No member profiles found." />}</div>
  </div>;
};
const Roles = ({ data, onSaved }: { data: any; onSaved: () => void }) => { const [selectedId, setSelectedId] = useState<number | null>(null); const [matrix, setMatrix] = useState<any[]>([]); const role = useMemo(() => data.roles.find((item: any) => item.id === selectedId) || data.roles[0], [data, selectedId]); useEffect(() => { if (!role) return; setSelectedId(role.id); setMatrix((data.sections || []).map((section: any) => { const current = data.permissions.find((permission: any) => permission.role_id === role.id && permission.section_slug === section.slug) || {}; return { sectionSlug: section.slug, canView: !!current.can_view, canCreate: !!current.can_create, canEdit: !!current.can_edit, canDelete: !!current.can_delete, canManage: !!current.can_manage }; })); }, [role?.id, data]); const toggle = (index: number, key: string) => setMatrix((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, [key]: !row[key] } : row)); return <div><Header eyebrow="Permission matrix" title="Roles & responsibilities" /><select value={role?.id || ''} onChange={(event) => setSelectedId(Number(event.target.value))} className="mt-5 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-bold text-slate-800">{data.roles.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px]"><thead className="text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="p-2 text-left">Section</th>{actions.map((action) => <th key={action} className="p-2 text-center">{action}</th>)}</tr></thead><tbody>{matrix.map((row, index) => <tr key={row.sectionSlug} className="border-t border-slate-100"><td className="p-3 text-sm font-bold text-slate-700">{row.sectionSlug}</td>{['canView','canCreate','canEdit','canDelete','canManage'].map((key) => <td key={key} className="p-3 text-center"><input type="checkbox" checked={row[key]} onChange={() => toggle(index, key)} /></td>)}</tr>)}</tbody></table></div><button onClick={async () => { if (role) { await db.phantom.updateRolePermissions(role.id, matrix); onSaved(); } }} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase text-white"><SaveIcon />Save permission matrix</button></div> };

const MemberPermissions = ({ members, sections, onSaved }: { members: any[]; sections: any[]; onSaved: () => void }) => {
  const [memberId, setMemberId] = useState('');
  const [matrix, setMatrix] = useState<any[]>([]);
  useEffect(() => { setMatrix(sections.map((section) => ({ sectionSlug: section.slug, canView: false, canCreate: false, canEdit: false, canDelete: false, canManage: false }))); }, [sections]);
  const toggle = (index: number, key: string) => setMatrix((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, [key]: !row[key] } : row));
  return <div><Header eyebrow="Granular control" title="Member Permission Overrides" /><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">These overrides are enforced by the Worker. Members cannot grant themselves permissions. Saving a row explicitly grants or denies each action for the selected member.</p><select value={memberId} onChange={(event) => setMemberId(event.target.value)} className="mt-5 w-full max-w-md rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-bold text-slate-800"><option value="">Choose member</option>{members.filter((member) => member.status !== 'archived').map((member) => <option key={member.id} value={member.id}>{member.member_code} · {member.name} · {member.role_name || member.role_code}</option>)}</select>{memberId && <><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px]"><thead className="text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="p-2 text-left">Section</th>{actions.map((action) => <th key={action} className="p-2 text-center">{action}</th>)}</tr></thead><tbody>{matrix.map((row, index) => <tr key={row.sectionSlug} className="border-t border-slate-100"><td className="p-3 text-sm font-bold text-slate-700">{row.sectionSlug}</td>{['canView','canCreate','canEdit','canDelete','canManage'].map((key) => <td key={key} className="p-3 text-center"><input type="checkbox" checked={row[key]} onChange={() => toggle(index, key)} /></td>)}</tr>)}</tbody></table></div><button onClick={async () => { await db.phantom.updateMemberPermissions(Number(memberId), matrix); onSaved(); }} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase text-white"><SaveIcon />Save member permissions</button></>}</div>
};

const WebsiteAdmins = ({ data, members, onSaved }: { data: any; members: any[]; onSaved: () => void }) => { const [profileId, setProfileId] = useState(''); const [permissions, setPermissions] = useState<string[]>([]); const toggle = (permission: string) => setPermissions((current) => current.includes(permission) ? current.filter((item) => item !== permission) : [...current, permission]); return <div><Header eyebrow="Delegated website control" title="Website Administrators" /><div className="mt-5 rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><p className="text-sm font-black text-emerald-900">Assign Website Admin</p><div className="mt-3 flex flex-col gap-3 lg:flex-row"><select value={profileId} onChange={(event) => setProfileId(event.target.value)} className="flex-1 rounded-xl border border-emerald-200 bg-white px-3 py-2.5 text-sm"><option value="">Choose active member</option>{members.filter((member) => member.status === 'active').map((member) => <option key={member.id} value={member.id}>{member.member_code} · {member.name}</option>)}</select><button disabled={!profileId} onClick={async () => { await db.phantom.assignWebsiteAdmin({ memberProfileId: Number(profileId), permissions }); setProfileId(''); setPermissions([]); onSaved(); }} className="rounded-xl bg-emerald-600 px-4 py-2.5 text-xs font-black uppercase text-white disabled:opacity-50">{profileId && (data.admins || []).some((admin: any) => String(admin.member_profile_id) === profileId) ? 'Save permissions' : 'Assign'}</button></div><div className="mt-4 flex flex-wrap gap-2">{(data.availablePermissions || []).map((permission: string) => <label key={permission} className={`cursor-pointer rounded-lg border px-3 py-2 text-xs font-bold ${permissions.includes(permission) ? 'border-emerald-500 bg-emerald-600 text-white' : 'border-emerald-200 bg-white text-emerald-700'}`}><input className="sr-only" type="checkbox" checked={permissions.includes(permission)} onChange={() => toggle(permission)} />{permission.replace('.', ' ')}</label>)}</div></div><div className="mt-5 space-y-3">{(data.admins || []).map((admin: any) => <article key={admin.id} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-100 p-5"><div><p className="font-black text-slate-900">{admin.name}</p><p className="mt-1 text-xs text-slate-500">{admin.member_code} · {admin.email}</p></div><div className="flex gap-2"><Status status={admin.status} /><button onClick={() => { setProfileId(String(admin.member_profile_id)); setPermissions((data.permissions || []).filter((permission: any) => permission.website_admin_id === admin.id && permission.allowed === 1).map((permission: any) => permission.permission_key)); window.scrollTo({ top: 0, behavior: 'smooth' }); }} className="mini-button text-emerald-700">Edit permissions</button><button onClick={async () => { await db.phantom.updateWebsiteAdmin(admin.id, { status: admin.status === 'active' ? 'suspended' : 'active' }); onSaved(); }} className="mini-button">{admin.status === 'active' ? 'Suspend' : 'Activate'}</button><button onClick={async () => { await db.phantom.updateWebsiteAdmin(admin.id, { status: 'removed' }); onSaved(); }} className="mini-button text-red-600">Remove</button></div></article>)}{!(data.admins || []).length && <Empty label="No Website Admins assigned." />}</div></div> };

const Codenames = ({ data, members, onSaved }: { data: any; members: any[]; onSaved: () => void }) => {
  const [input, setInput] = useState('');
  const [pool, setPool] = useState<'member' | 'founding'>('member');
  const [reserve, setReserve] = useState(false);
  const [assignCodenameId, setAssignCodenameId] = useState('');
  const [assignMemberId, setAssignMemberId] = useState('');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const founding = (data.codenames || []).filter((item: any) => item.pool === 'founding');
  const memberPool = (data.codenames || []).filter((item: any) => item.pool !== 'founding');
  const assignable = founding.filter((item: any) => item.status === 'available');
  const plainEstimate = input.trim().startsWith('[') || input.trim().startsWith('{')
    ? 'JSON batch'
    : `${input.split(/[\n,;]+/).map((item) => item.trim()).filter(Boolean).length || 0} names`;

  const addBatch = async () => {
    if (!input.trim()) { setMessage({ type: 'error', text: 'Paste one or more codenames first.' }); return; }
    setBusy(true); setMessage(null);
    try {
      const result = await db.phantom.addCodenamesBatch({ input, pool, reserve });
      setInput('');
      setMessage({ type: 'success', text: result.message || 'Codenames added.' });
      onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not add this codename batch.' }); }
    finally { setBusy(false); }
  };

  return <div>
    <Header eyebrow="Identity governance" title="Codename Pools" />
    <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Add a single codename, a comma/new-line list, or a JSON batch. Member and Founding pools remain separate, and every name is checked before the whole batch is saved.</p>
    <section className="mt-5 rounded-2xl border border-emerald-100 bg-emerald-50 p-5">
      <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-black text-emerald-950">Add codenames in bulk</p><p className="mt-1 text-xs text-emerald-800">Plain text: <strong>NOVA, ORBIT, PULSE</strong> · JSON: <code className="font-bold">{'[{"name":"NOVA","pool":"member"}]'}</code></p></div><span className="rounded-full border border-emerald-200 bg-white px-3 py-1.5 text-xs font-black text-emerald-700">{plainEstimate}</span></div>
      <textarea value={input} onChange={(event) => setInput(event.target.value)} rows={4} placeholder={`NOVA, ORBIT, PULSE

or paste JSON: ["NOVA", "ORBIT"]`} className="mt-4 w-full resize-y rounded-xl border border-emerald-200 bg-white px-4 py-3 font-mono text-sm text-slate-700 outline-none focus:border-emerald-500" />
      <div className="mt-3 grid gap-3 sm:grid-cols-[1fr_auto_auto]"><select value={pool} onChange={(event) => setPool(event.target.value as 'member' | 'founding')} className="rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm font-bold text-emerald-800"><option value="member">Member Pool</option><option value="founding">Founding Pool</option></select><label className="flex items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm font-bold text-emerald-800"><input type="checkbox" checked={reserve} onChange={(event) => setReserve(event.target.checked)} />Reserve all</label><button disabled={busy} onClick={() => void addBatch()} className="inline-flex items-center justify-center gap-2 rounded-xl bg-emerald-600 px-5 py-3 text-xs font-black uppercase tracking-wider text-white disabled:opacity-60"><Plus className="h-4 w-4" />{busy ? 'Adding…' : 'Add codenames'}</button></div>
      {message && <p role="status" className={`mt-3 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-white text-emerald-800' : 'bg-red-50 text-red-700'}`}>{message.text}</p>}
    </section>
    <div className="mt-4 grid gap-3 rounded-2xl border border-slate-100 bg-slate-50 p-4 sm:grid-cols-[1fr_1fr_auto]"><select value={assignCodenameId} onChange={(event) => setAssignCodenameId(event.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm"><option value="">Direct founding assignment</option>{assignable.map((item: any) => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select><select value={assignMemberId} onChange={(event) => setAssignMemberId(event.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm"><option value="">Choose member profile</option>{members.filter((member) => ['active', 'pending_activation'].includes(member.status) && !member.codename).map((member) => <option key={member.id} value={member.id}>{member.member_code} · {member.name}</option>)}</select><button disabled={!assignCodenameId || !assignMemberId} onClick={async () => { try { await db.phantom.assignCodename(Number(assignCodenameId), Number(assignMemberId)); setAssignCodenameId(''); setAssignMemberId(''); setMessage({ type: 'success', text: 'Founding codename assigned.' }); onSaved(); } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not assign this codename.' }); } }} className="rounded-xl bg-emerald-600 px-4 py-2.5 text-xs font-black uppercase text-white disabled:opacity-50">Assign</button></div>
    <CodenamePool title="Founding Codename Pool" description="PHANTOM, NEXUS, GHOST, FALCON, QUANTUM, MATRIX, and deliberate custom founding identities." items={founding} onSaved={onSaved} />
    <CodenamePool title="Member Ballot Pool" description="Only standard Member-path users can see and ballot from these codenames." items={memberPool} onSaved={onSaved} />
    <details className="mt-5 rounded-2xl border border-slate-100 p-4"><summary className="cursor-pointer text-sm font-black text-slate-800">Codename history</summary><div className="mt-3 space-y-2">{(data.history || []).length ? <RecentItems items={data.history || []} label="codename events" render={(item) => <div key={item.id} className="rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-600">{item.event_type} · codename #{item.codename_id} · {item.created_at}</div>} /> : <p className="text-xs text-slate-500">No codename history yet.</p>}</div></details>
  </div>;
};

const CodenamePool = ({ title, description, items, onSaved }: { title: string; description: string; items: any[]; onSaved: () => void }) => { const available = items.filter((item: any) => item.status === 'available').length; return <section className="mt-7"><div><h4 className="font-black text-slate-900">{title}</h4><p className="mt-1 text-xs text-slate-500">{description}</p></div>{available === 0 && <div className="mt-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs font-bold text-amber-800">{title.startsWith('Member') ? 'Member Codename Pool Exhausted — add more Member Pool codenames above.' : 'Founding Codename Pool Exhausted — add a deliberate custom Founding Pool codename or explicitly release one.'}</div>}<div className="mt-3 overflow-x-auto"><table className="w-full min-w-[650px]"><thead className="text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="p-3 text-left">Codename</th><th>Pool</th><th>Status</th><th>Owner</th><th>Claimed</th><th className="text-right">Action</th></tr></thead><tbody>{items.map((item: any) => <tr key={item.id} className="border-t border-slate-100"><td className="p-3 font-black text-slate-900">{item.display_name}</td><td className="text-xs font-bold text-slate-500">{item.pool === 'founding' ? 'Founding' : 'Member'}</td><td><Status status={item.status} /></td><td className="text-sm text-slate-600">{item.owner_name || '—'}</td><td className="text-sm text-slate-500">{item.claimed_at || '—'}</td><td className="p-3 text-right">{item.status === 'available' && <button onClick={async () => { await db.phantom.updateCodename(item.id, { action: 'reserve' }); onSaved(); }} className="mini-button">Reserve</button>}{item.status === 'reserved' && <button onClick={async () => { await db.phantom.updateCodename(item.id, { action: 'unreserve' }); onSaved(); }} className="mini-button">Unreserve</button>}{item.status === 'claimed' && <button onClick={async () => { if (window.confirm(`Release ${item.display_name}? This must be explicit.`)) { await db.phantom.releaseCodename(item.id, { confirm: true, mode: 'retired' }); onSaved(); } }} className="mini-button text-red-600">Release</button>}{['available','reserved'].includes(item.status) && <button onClick={async () => { await db.phantom.updateCodename(item.id, { action: 'retire' }); onSaved(); }} className="ml-1 mini-button text-red-600">Remove</button>}</td></tr>)}</tbody></table>{!items.length && <Empty label="No codenames in this pool yet." />}</div></section>; }


const AuditLog = ({ logs }: { logs: any[] }) => <div><Header eyebrow="Protected history" title="Audit logs" /><p className="mt-2 text-sm leading-6 text-slate-500">Audit records are protected for organization accountability. The newest three are shown first; open older entries only when needed.</p><div className="mt-5 space-y-2">{logs.length ? <RecentItems items={logs} label="audit entries" render={(log) => <article key={log.id} className="rounded-xl border border-slate-100 p-4"><p className="text-sm font-black text-slate-800">{String(log.action || '').replace(/\./g, ' ')}</p><p className="mt-1 text-xs text-slate-500">{log.actor_name || 'System'} · {log.actor_member_code || '—'} · {log.created_at}</p></article>} /> : <Empty label="No audit log records yet." />}</div></div>;

const RecycleBin = ({ items, onChanged }: { items: any[]; onChanged: () => void }) => {
  const [busy, setBusy] = useState<number | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const restore = async (item: any) => {
    setBusy(item.id); setMessage(null);
    try { const result: any = await db.phantom.restoreRecycleBin(item.id); setMessage({ type: 'success', text: result.message || `${item.title} restored.` }); onChanged(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not restore this item.' }); }
    finally { setBusy(null); }
  };
  const purge = async (item: any) => {
    if (!window.confirm(`Permanently delete “${item.title}”? It cannot be restored afterwards.`)) return;
    setBusy(item.id); setMessage(null);
    try { await db.phantom.purgeRecycleBin(item.id); setMessage({ type: 'success', text: 'Recycle-bin item permanently deleted.' }); onChanged(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not permanently delete this item.' }); }
    finally { setBusy(null); }
  };
  return <div><Header eyebrow="Recoverable deletion" title="Recycle Bin" /><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Deleted applications, subscribers, contact messages, withdrawn notifications, and inbox notices come here first. Restore an item or permanently remove it when you are certain.</p>{message && <p role="status" className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}<div className="mt-6 space-y-3">{items.length ? <RecentItems items={items} label="recycle-bin items" render={(item) => <article key={item.id} className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-100 bg-slate-50 p-4"><div className="min-w-0"><p className="font-black text-slate-900">{item.title}</p><p className="mt-1 text-[10px] font-black uppercase tracking-wider text-emerald-700">{String(item.resource_type || '').replace(/_/g, ' ')}</p><p className="mt-2 text-xs text-slate-500">Deleted {item.deleted_at}{item.deleted_by_name ? ` · ${item.deleted_by_name}` : ''}</p></div><div className="flex shrink-0 flex-wrap gap-2"><button disabled={busy === item.id} onClick={() => void restore(item)} className="rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700 hover:bg-emerald-100 disabled:opacity-60">{busy === item.id ? 'Working…' : 'Restore'}</button><button disabled={busy === item.id} onClick={() => void purge(item)} className="rounded-xl border border-red-100 bg-red-50 px-3 py-2 text-xs font-black text-red-600 hover:bg-red-100 disabled:opacity-60">Delete forever</button></div></article>} /> : <Empty label="The Recycle Bin is empty." />}</div></div>;
};

const SharingControl = ({ data, members, onSaved }: { data: any; members: any[]; onSaved: () => void }) => {
  const [busy, setBusy] = useState<string | null>(null);
  const [message, setMessage] = useState<{ type: 'error' | 'success'; text: string } | null>(null);
  const shareMap = new Map((data.permissions || []).map((item: any) => [item.member_profile_id, Number(item.can_share) === 1]));
  const downloadMap = new Map((data.permissions || []).map((item: any) => [item.member_profile_id, Number(item.can_download) === 1]));
  const activeMembers = members.filter((member) => member.status === 'active' && member.role_code !== 'phantom');
  const refresh = async (work: () => Promise<unknown>, key: string, success: string) => {
    setBusy(key); setMessage({ type: 'success', text: 'Saving changes in the background…' });
    try { await work(); setMessage({ type: 'success', text: success }); onSaved(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not save this permission.' }); }
    finally { setBusy(null); }
  };
  return <div><Header eyebrow="Controlled document access" title="Vault sharing and downloads" /><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Sharing and downloading have separate global master switches and separate member permissions. PHANTOM can pause access immediately; existing share links remain view-only when downloads are disabled.</p><div className="mt-6 grid gap-4 lg:grid-cols-2"><section className="rounded-2xl border border-emerald-100 bg-[#f3fcf6] p-5"><p className="font-black text-emerald-950">Global sharing master switch</p><p className="mt-1 text-sm text-emerald-800">{data.globalEnabled ? 'Public read-only links are live.' : 'All public share links are paused.'}</p><button disabled={busy === 'global-share'} onClick={() => void refresh(() => db.phantom.setGlobalSharing(!data.globalEnabled), 'global-share', data.globalEnabled ? 'Global sharing paused.' : 'Global sharing enabled.')} className={`mt-4 rounded-xl px-4 py-3 text-xs font-black uppercase tracking-wider text-white disabled:opacity-60 ${data.globalEnabled ? 'bg-rose-500 hover:bg-rose-600' : 'bg-emerald-600 hover:bg-emerald-700'}`}>{busy === 'global-share' ? 'Saving…' : data.globalEnabled ? 'Pause sharing' : 'Enable sharing'}</button></section><section className="rounded-2xl border border-sky-100 bg-[#f2f9ff] p-5"><p className="font-black text-slate-800">Global document-download switch</p><p className="mt-1 text-sm text-slate-600">{data.downloadsGloballyEnabled ? 'Authorized internal downloads and allowed shared downloads are live.' : 'All document downloads and shared-page print controls are paused.'}</p><button disabled={busy === 'global-download'} onClick={() => void refresh(() => db.phantom.setGlobalDownloads(!data.downloadsGloballyEnabled), 'global-download', data.downloadsGloballyEnabled ? 'Global downloads paused.' : 'Global downloads enabled.')} className={`mt-4 rounded-xl px-4 py-3 text-xs font-black uppercase tracking-wider text-white disabled:opacity-60 ${data.downloadsGloballyEnabled ? 'bg-rose-500 hover:bg-rose-600' : 'bg-sky-600 hover:bg-sky-700'}`}>{busy === 'global-download' ? 'Saving…' : data.downloadsGloballyEnabled ? 'Pause downloads' : 'Enable downloads'}</button></section></div>{message && <p className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-800' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}<section className="mt-7"><div className="flex items-end justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Member permissions</p><h4 className="mt-1 text-lg font-black text-slate-900">Share and download controls</h4></div><span className="text-xs font-bold text-slate-400">{activeMembers.length} active members</span></div><div className="mt-4 overflow-x-auto rounded-2xl border border-slate-100"><table className="w-full min-w-[760px] text-left"><thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="px-4 py-3">Member</th><th>Responsibility</th><th>CAL</th><th className="px-4 py-3 text-right">Share button</th><th className="px-4 py-3 text-right">Download button</th></tr></thead><tbody>{activeMembers.map((member) => { const canShare = shareMap.get(member.id) || false; const canDownload = downloadMap.get(member.id) || false; return <tr key={member.id} className="border-t border-slate-100"><td className="px-4 py-3"><p className="font-bold text-slate-900">{member.name}</p><p className="text-xs text-slate-500">{member.member_code} · {member.email}</p></td><td className="text-sm text-slate-600">{member.role_name || member.role_code}</td><td className="text-sm font-black text-emerald-700">{Number(member.points || 0).toLocaleString()} CAL</td><td className="px-4 py-3 text-right"><button disabled={busy === `share-${member.id}`} onClick={() => void refresh(() => db.phantom.setMemberSharing(member.id, !canShare), `share-${member.id}`, canShare ? `Sharing disabled for ${member.name}.` : `Sharing enabled for ${member.name}.`)} className={`rounded-lg px-3 py-2 text-xs font-black disabled:opacity-60 ${canShare ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{busy === `share-${member.id}` ? 'Saving…' : canShare ? 'Enabled' : 'Disabled'}</button></td><td className="px-4 py-3 text-right"><button disabled={busy === `download-${member.id}`} onClick={() => void refresh(() => db.phantom.setMemberDownloads(member.id, !canDownload), `download-${member.id}`, canDownload ? `Downloads disabled for ${member.name}.` : `Downloads enabled for ${member.name}.`)} className={`rounded-lg px-3 py-2 text-xs font-black disabled:opacity-60 ${canDownload ? 'bg-sky-50 text-sky-700' : 'bg-slate-100 text-slate-500'}`}>{busy === `download-${member.id}` ? 'Saving…' : canDownload ? 'Enabled' : 'Disabled'}</button></td></tr>; })}</tbody></table>{!activeMembers.length && <Empty label="No active members are available for sharing or download permissions." />}</div></section></div>;
};
const CommunityAdministration = ({ groups, reports, members, onSaved }: { groups: any[]; reports: any[]; members: any[]; onSaved: () => void }) => {
  const [busy, setBusy] = useState<string | null>(null);
  const [assignProfileId, setAssignProfileId] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [selectedGroup, setSelectedGroup] = useState<any | null>(null);
  const [joinRequests, setJoinRequests] = useState<any[]>([]);
  const groupAction = async (group: any, patch: any) => {
    setBusy(`group-${group.id}`); setMessage(null);
    try { await db.community.updateGroup(group.id, patch); setMessage({ type: 'success', text: `${group.title} updated.` }); onSaved(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update this group.' }); }
    finally { setBusy(null); }
  };
  const inspectGroup = async (group: any) => {
    setBusy(`inspect-${group.id}`); setMessage(null);
    try {
      const [detail, requests] = await Promise.all([db.community.group(group.id), db.community.groupRequests(group.id)]);
      setSelectedGroup(detail); setJoinRequests(requests);
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not inspect this group.' }); }
    finally { setBusy(null); }
  };
  const updateGroupMember = async (member: any, data: any) => {
    if (!selectedGroup) return;
    setBusy(`member-${member.id}`); setMessage(null);
    try {
      await db.community.updateGroupMember(selectedGroup.id, member.id, data);
      const detail = await db.community.group(selectedGroup.id); setSelectedGroup(detail); setMessage({ type: 'success', text: 'Group member updated.' }); onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update this group member.' }); }
    finally { setBusy(null); }
  };
  const resolveRequest = async (request: any, action: 'approve' | 'reject') => {
    if (!selectedGroup) return;
    setBusy(`request-${request.id}`); setMessage(null);
    try {
      await db.community.reviewGroupRequest(selectedGroup.id, request.id, action);
      const [detail, requests] = await Promise.all([db.community.group(selectedGroup.id), db.community.groupRequests(selectedGroup.id)]);
      setSelectedGroup(detail); setJoinRequests(requests); setMessage({ type: 'success', text: action === 'approve' ? 'Join request approved.' : 'Join request rejected.' }); onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not review this join request.' }); }
    finally { setBusy(null); }
  };
  const resolveReport = async (report: any, status: 'reviewed' | 'resolved' | 'dismissed') => {
    setBusy(`report-${report.id}`); setMessage(null);
    try { await db.communityAdmin.updatePublicReport(report.id, status); setMessage({ type: 'success', text: 'Public report updated.' }); onSaved(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update this report.' }); }
    finally { setBusy(null); }
  };
  return <div><Header eyebrow="Community operations" title="Community Control" /><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Manage private groups, member roles, join requests, Telegram sync, and public-community reports from PHANTOM. Every action is re-authorized on the Worker.</p>{message && <p role="status" className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}<section className="mt-6"><div className="flex items-end justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Private Code Rx groups</p><h4 className="mt-1 text-lg font-black text-slate-900">Group discovery, roles, and Telegram sync</h4></div><span className="text-xs font-bold text-slate-400">{groups.length} groups</span></div><div className="mt-4 space-y-3">{groups.length ? <RecentItems items={groups} label="groups" render={(group) => <article key={group.id} className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-100 p-5"><div><p className="font-black text-slate-900">{group.title}</p><p className="mt-1 text-sm text-slate-500">{group.description || 'No description'} · {group.member_count} members</p><p className="mt-2 text-[10px] font-black uppercase tracking-wider text-emerald-700">Group #{group.id} · {group.join_mode} · {group.status}</p></div><div className="flex flex-wrap gap-2"><button disabled={busy === `inspect-${group.id}`} onClick={() => void inspectGroup(group)} className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700">Manage</button><select value={group.join_mode} disabled={busy === `group-${group.id}`} onChange={(event) => void groupAction(group, { joinMode: event.target.value })} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold"><option value="invite">Invite only</option><option value="open">Open to Members</option><option value="approval">Approval required</option><option value="assigned">PHANTOM assigned</option></select><button disabled={busy === `group-${group.id}`} onClick={() => void groupAction(group, { status: group.status === 'locked' ? 'active' : 'locked' })} className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-black text-amber-800">{group.status === 'locked' ? 'Unlock' : 'Lock'}</button><button disabled={busy === `group-${group.id}`} onClick={() => { const chatId = window.prompt('Telegram group chat ID (leave blank to clear):', group.telegram_chat_id || ''); if (chatId !== null) void groupAction(group, { telegramChatId: chatId }); }} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600">Telegram chat ID</button><button disabled={busy === `group-${group.id}`} onClick={() => void groupAction(group, { telegramSyncEnabled: !group.telegram_sync_enabled })} className={`rounded-lg px-3 py-2 text-xs font-black ${group.telegram_sync_enabled ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>Telegram {group.telegram_sync_enabled ? 'ON' : 'OFF'}</button></div></article>} /> : <Empty label="No private groups have been created yet." />}</div></section>{selectedGroup && <section className="mt-7 rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Group inspector</p><h4 className="mt-1 text-xl font-black text-slate-900">{selectedGroup.title}</h4></div><button onClick={() => setSelectedGroup(null)} className="rounded-lg p-2 text-slate-400 hover:bg-white"><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-6 lg:grid-cols-2"><div><p className="text-sm font-black text-slate-800">Members</p><div className="mt-3 space-y-2">{(selectedGroup.members || []).map((member: any) => <div key={member.id} className="flex items-center justify-between gap-3 rounded-xl border border-emerald-100 bg-white px-3 py-3"><span><strong className="block text-sm text-slate-800">{member.codename}</strong><small className="text-xs text-slate-500">{member.role}</small></span>{member.role !== 'owner' && <div className="flex gap-2"><select value={member.role} disabled={busy === `member-${member.id}`} onChange={(event) => void updateGroupMember(member, { role: event.target.value })} className="rounded-lg border border-slate-200 px-2 py-1.5 text-xs"><option value="admin">Admin</option><option value="moderator">Moderator</option><option value="member">Member</option></select><button disabled={busy === `member-${member.id}`} onClick={() => void updateGroupMember(member, { action: 'remove' })} className="rounded-lg border border-red-100 bg-red-50 px-2 py-1.5 text-xs font-black text-red-600">Remove</button></div>}</div>)}</div><div className="mt-3 flex gap-2"><select value={assignProfileId} onChange={(event) => setAssignProfileId(event.target.value)} className="min-w-0 flex-1 rounded-lg border border-emerald-200 bg-white px-2 py-2 text-xs"><option value="">Assign active member</option>{members.filter((member) => !selectedGroup.members?.some((existing: any) => Number(existing.id) === Number(member.id))).map((member) => <option key={member.id} value={member.id}>{member.member_code} · {member.name}</option>)}</select><button disabled={!assignProfileId} onClick={() => { void updateGroupMember({ id: Number(assignProfileId) }, { action: 'assign' }); setAssignProfileId(''); }} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-black text-white disabled:opacity-50">Assign</button></div></div><div><p className="text-sm font-black text-slate-800">Pending join requests</p><div className="mt-3 space-y-2">{joinRequests.length ? joinRequests.map((request) => <div key={request.id} className="flex items-center justify-between gap-3 rounded-xl border border-emerald-100 bg-white px-3 py-3"><span><strong className="block text-sm text-slate-800">{request.codename}</strong><small className="text-xs text-slate-500">{request.message || 'No request message'}</small></span><div className="flex gap-2"><button disabled={busy === `request-${request.id}`} onClick={() => void resolveRequest(request, 'approve')} className="rounded-lg bg-emerald-600 px-2 py-1.5 text-xs font-black text-white">Approve</button><button disabled={busy === `request-${request.id}`} onClick={() => void resolveRequest(request, 'reject')} className="rounded-lg border border-slate-200 px-2 py-1.5 text-xs font-black text-slate-600">Reject</button></div></div>) : <p className="rounded-xl border border-dashed border-emerald-200 bg-white p-4 text-sm text-slate-500">No pending join requests.</p>}</div></div></div></section>}<section className="mt-8"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Public community moderation</p><h4 className="mt-1 text-lg font-black text-slate-900">Reports waiting for review</h4></div><div className="mt-4 space-y-3">{reports.length ? <RecentItems items={reports} label="public reports" render={(report) => <article key={report.id} className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-slate-100 bg-slate-50 p-4"><div><p className="font-bold text-slate-900">{report.post_id ? `Reported post #${report.post_id}` : `Reported discussion #${report.thread_id}`}</p><p className="mt-1 text-sm text-slate-600">{report.reason}</p><p className="mt-2 text-xs text-slate-400">{report.created_at}</p></div><div className="flex gap-2"><button disabled={busy === `report-${report.id}`} onClick={() => void resolveReport(report, 'reviewed')} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600">Review</button><button disabled={busy === `report-${report.id}`} onClick={() => void resolveReport(report, 'resolved')} className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700">Resolve</button><button disabled={busy === `report-${report.id}`} onClick={() => void resolveReport(report, 'dismissed')} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-500">Dismiss</button></div></article>} /> : <Empty label="No open public reports." />}</div></section></div>;
};

const CommunityMediaManagement = ({ data, onSaved }: { data: any; onSaved: () => void }) => {
  const [scope, setScope] = useState<'global' | 'private' | 'public_forum' | 'public_chat' | 'group'>('global');
  const [groupId, setGroupId] = useState('');
  const [busy, setBusy] = useState<string | null>(null);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const scopeType = scope === 'global' ? 'global' : scope === 'group' ? 'group' : 'area';
  const scopeKey = scope === 'global' ? 'global' : scope === 'group' ? `group:${groupId}` : scope;
  const mediaTypes = ['all', 'image', 'video', 'document', 'pdf', 'audio', 'other'];
  const labels: Record<string, string> = { all: 'All-media master switch', image: 'Images', video: 'Videos', document: 'Documents', pdf: 'PDFs', audio: 'Audio / voice', other: 'Other files' };
  const formatBytes = (value: number) => value < 1024 * 1024 ? `${Math.round(value / 1024)} KB` : `${(value / 1024 / 1024).toFixed(2)} MB`;
  const settingFor = (mediaType: string) => (data.settings || []).find((item: any) => item.scope_key === scopeKey && item.media_type === mediaType) || { enabled: 0, max_bytes: 0, storage_limit_bytes: 0, allowed_mimes_json: '[]', telegram_auto_delete_after_sync: 0 };
  const save = async (mediaType: string, patch: any) => {
    if (scope === 'group' && !groupId.trim()) { setMessage({ type: 'error', text: 'Enter a group ID before setting a group media override.' }); return; }
    const current = settingFor(mediaType);
    setBusy(mediaType); setMessage(null);
    try {
      const payload: any = {
        scopeType,
        scopeKey,
        mediaType,
        enabled: patch.enabled ?? Number(current.enabled) === 1,
        maxBytes: patch.maxBytes ?? Number(current.max_bytes || 0),
        storageLimitBytes: patch.storageLimitBytes ?? Number(current.storage_limit_bytes || 0),
        allowedMimes: patch.allowedMimes ?? (() => { try { return JSON.parse(current.allowed_mimes_json || '[]'); } catch { return []; } })(),
      };
      if (scope === 'global' && mediaType === 'all') payload.telegramAutoDeleteAfterSync = patch.telegramAutoDeleteAfterSync ?? Number(current.telegram_auto_delete_after_sync || 0) === 1;
      await db.communityAdmin.saveMediaSetting(payload);
      setMessage({ type: 'success', text: patch.telegramAutoDeleteAfterSync !== undefined ? 'Telegram storage protection saved.' : `${labels[mediaType]} saved.` });
      onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not save this media setting.' }); }
    finally { setBusy(null); }
  };
  const retention = data.telegramRetention || {};
  const autoDeleteAfterSync = Boolean(retention.autoDeleteAfterSync ?? Number(settingFor('all').telegram_auto_delete_after_sync || 0) === 1);
  const maxSyncBytes = Number(retention.maxSyncBytes || 20 * 1024 * 1024);
  const retryTelegramItem = async (id: number) => {
    setBusy(`retry-${id}`); setMessage(null);
    try {
      const result = await db.community.retryAttachmentTelegramSync(id);
      setMessage({ type: 'success', text: result.message || 'Telegram media sync completed.' });
      onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Telegram media sync could not be retried.' }); }
    finally { setBusy(null); }
  };

  return <div>
    <Header eyebrow="R2-backed community files" title="Media Management" />
    <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Text chat always stays available. These controls regulate images, video, files, PDFs, and audio at global, area, and group levels. Backend enforcement applies even if a client bypasses the interface.</p>

    <div className="mt-5 grid gap-3 rounded-2xl border border-emerald-100 bg-emerald-50 p-5 md:grid-cols-[1fr_auto]">
      <div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-700">Storage used</p><p className="mt-1 text-3xl font-black text-emerald-950">{formatBytes(Number(data.totals?.storageBytes || 0))}</p><p className="mt-1 text-xs text-emerald-800">{Number(data.totals?.fileCount || 0)} active files</p></div>
      <div className="flex flex-wrap items-center gap-2"><select value={scope} onChange={(event) => setScope(event.target.value as typeof scope)} className="rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm font-bold text-emerald-800"><option value="global">Global</option><option value="private">Private Community</option><option value="public_forum">Public Forum</option><option value="public_chat">Public Chat</option><option value="group">Specific Group</option></select>{scope === 'group' && <input value={groupId} onChange={(event) => setGroupId(event.target.value)} placeholder="Group ID" className="w-28 rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm" />}</div>
    </div>

    {scope === 'global' && <section className={`mt-5 rounded-2xl border p-5 ${autoDeleteAfterSync ? 'border-sky-200 bg-sky-50' : 'border-slate-200 bg-slate-50'}`}>
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="max-w-3xl"><p className="text-[10px] font-black uppercase tracking-widest text-sky-700">Telegram storage protection</p><h3 className="mt-2 text-lg font-black text-slate-900">Delete R2 chat media after verified Telegram sync</h3><p className="mt-2 text-sm leading-6 text-slate-600">When ON, a private-chat file is accepted only when that chat has an active Telegram target. Code Rx sends it privately to Telegram, waits for Telegram to confirm delivery, then deletes the R2 object. A failed sync is retained safely for retry; it is never deleted early.</p><p className="mt-2 text-xs font-bold text-sky-800">Safe sync cap: {formatBytes(maxSyncBytes)} per file. Text chat is never affected.</p>{Number(retention.retryRequiredCount || 0) > 0 && <p className="mt-2 text-xs font-black text-amber-800">{retention.retryRequiredCount} media item{Number(retention.retryRequiredCount) === 1 ? '' : 's'} need Telegram or R2-cleanup retry.</p>}</div>
        <button disabled={busy === 'all'} onClick={() => void save('all', { telegramAutoDeleteAfterSync: !autoDeleteAfterSync })} className={`rounded-xl px-4 py-3 text-xs font-black uppercase tracking-wider disabled:opacity-60 ${autoDeleteAfterSync ? 'bg-sky-600 text-white hover:bg-sky-700' : 'border border-slate-300 bg-white text-slate-700 hover:bg-slate-100'}`}>{busy === 'all' ? 'Saving…' : autoDeleteAfterSync ? 'Disable protection' : 'Enable protection'}</button>
      </div>
    </section>}

    {scope === 'global' && (data.retryItems || []).length > 0 && <section className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-5"><p className="text-[10px] font-black uppercase tracking-widest text-amber-700">Protected local files awaiting cleanup</p><h3 className="mt-1 text-lg font-black text-amber-950">Retry Telegram delivery or R2 cleanup</h3><p className="mt-2 text-sm leading-6 text-amber-900">These files were deliberately retained because Telegram had not fully confirmed delivery or R2 cleanup. Retrying never deletes a file before Telegram confirmation.</p><div className="mt-4 space-y-2">{(data.retryItems || []).map((item: any) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200 bg-white px-4 py-3"><span><strong className="block text-sm text-slate-800">{item.originalName}</strong><small className="text-xs text-slate-500">{item.conversationTitle} · {item.mediaType} · {formatBytes(Number(item.sizeBytes || 0))} · {item.syncStatus}</small></span><button disabled={busy === `retry-${item.id}`} onClick={() => void retryTelegramItem(item.id)} className="rounded-lg border border-sky-200 bg-sky-50 px-3 py-2 text-xs font-black text-sky-800 disabled:opacity-60">{busy === `retry-${item.id}` ? 'Retrying…' : 'Retry Telegram'}</button></div>)}</div></section>}

    {message && <p role="status" className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}

    <section className="mt-6 overflow-x-auto rounded-2xl border border-slate-100"><table className="w-full min-w-[760px] text-left"><thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-400"><tr><th className="px-4 py-3">Media type</th><th>Enabled</th><th>Maximum file size</th><th>Storage cap</th><th>Allowed MIME types</th></tr></thead><tbody>{mediaTypes.map((mediaType) => { const setting = settingFor(mediaType); let mimes: string[] = []; try { mimes = JSON.parse(setting.allowed_mimes_json || '[]'); } catch { /* ignore */ } return <tr key={mediaType} className="border-t border-slate-100"><td className="px-4 py-4 font-bold text-slate-800">{labels[mediaType]}</td><td><button disabled={busy === mediaType} onClick={() => void save(mediaType, { enabled: Number(setting.enabled) !== 1 })} className={`rounded-lg px-3 py-2 text-xs font-black disabled:opacity-60 ${Number(setting.enabled) === 1 ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{busy === mediaType ? 'Saving…' : Number(setting.enabled) === 1 ? 'ON' : 'OFF'}</button></td><td><input type="number" min="0" defaultValue={Math.round(Number(setting.max_bytes || 0) / 1024 / 1024)} onBlur={(event) => { const mb = Math.max(0, Number(event.target.value) || 0); if (mb * 1024 * 1024 !== Number(setting.max_bytes || 0)) void save(mediaType, { maxBytes: Math.round(mb * 1024 * 1024) }); }} className="w-20 rounded-lg border border-slate-200 px-2 py-2 text-sm" /> <span className="text-xs text-slate-400">MB</span></td><td>{mediaType === 'all' ? <><input type="number" min="0" defaultValue={Math.round(Number(setting.storage_limit_bytes || 0) / 1024 / 1024)} onBlur={(event) => { const mb = Math.max(0, Number(event.target.value) || 0); if (mb * 1024 * 1024 !== Number(setting.storage_limit_bytes || 0)) void save(mediaType, { storageLimitBytes: Math.round(mb * 1024 * 1024) }); }} className="w-20 rounded-lg border border-slate-200 px-2 py-2 text-sm" /> <span className="text-xs text-slate-400">MB</span></> : <span className="text-xs text-slate-400">Inherited</span>}</td><td><input defaultValue={mimes.join(', ')} onBlur={(event) => void save(mediaType, { allowedMimes: event.target.value.split(',').map((item) => item.trim()).filter(Boolean) })} placeholder="image/png, image/jpeg" className="w-64 rounded-lg border border-slate-200 px-2 py-2 text-xs" /></td></tr>; })}</tbody></table></section>

    <div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{(data.byType || []).map((row: any) => <div key={row.mediaType} className="rounded-xl border border-slate-100 bg-slate-50 p-4"><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{row.mediaType}</p><p className="mt-2 font-black text-slate-900">{formatBytes(Number(row.storageBytes || 0))}</p><p className="mt-1 text-xs text-slate-500">{row.fileCount} files</p></div>)}</div>
    <section className="mt-6"><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Storage by private group</p><div className="mt-3 space-y-2">{(data.byGroup || []).map((group: any) => <div key={group.groupId} className="flex items-center justify-between rounded-xl border border-slate-100 px-4 py-3"><span><strong className="block text-sm text-slate-800">{group.groupTitle}</strong><small className="text-xs text-slate-500">{group.fileCount} files</small></span><strong className="text-sm text-emerald-700">{formatBytes(Number(group.storageBytes || 0))}</strong></div>)}{!(data.byGroup || []).length && <p className="text-sm text-slate-500">No private group media stored yet.</p>}</div></section>
  </div>;
};

const ScoreSystem = ({ rules, members, onSaved }: { rules: any[]; members: any[]; onSaved: () => void }) => {
  const [selectedId, setSelectedId] = useState('');
  const [history, setHistory] = useState<any[]>([]);
  const [action, setAction] = useState<'add' | 'deduct' | 'set'>('add');
  const [amount, setAmount] = useState('');
  const [reason, setReason] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const loadHistory = async (id: string) => { setSelectedId(id); setHistory([]); if (!id) return; try { setHistory(await db.phantom.scoreHistory(Number(id))); } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not load Calcitonin history.' }); } };
  const adjust = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!selectedId || !reason.trim() || !amount) { setMessage({ type: 'error', text: 'Choose a member, CAL amount, and reason.' }); return; }
    setBusy('adjust'); setMessage(null);
    try {
      const result = await db.phantom.adjustScore(Number(selectedId), { action, points: Number(amount), reason });
      setMessage({ type: 'success', text: `Calcitonins updated: ${result.data.delta >= 0 ? '+' : ''}${result.data.delta} CAL. Balance: ${result.data.balance} CAL.` });
      setAmount(''); setReason(''); await loadHistory(selectedId); onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update this Calcitonin balance.' }); }
    finally { setBusy(null); }
  };
  const updateRule = async (rule: any, change: { enabled?: boolean; points?: number }) => { setBusy(`rule-${rule.rule_key}`); setMessage(null); try { await db.phantom.updateScoreRule(rule.rule_key, change); setMessage({ type: 'success', text: 'Automatic Calcitonin rule saved.' }); onSaved(); } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update automatic Calcitonins.' }); } finally { setBusy(null); } };
  const activeMembers = members.filter((member) => member.status !== 'archived' && member.role_code !== 'phantom');
  const totalCalcitonins = activeMembers.reduce((total, member) => total + Number(member.points || 0), 0);
  const topMember = [...activeMembers].sort((left, right) => Number(right.points || 0) - Number(left.points || 0))[0];
  return <div><Header eyebrow="Verified contribution balance" title="Calcitonin system" /><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Calcitonins are Code Rx contribution units. <strong>CAL</strong> is the short form. PHANTOM can adjust a balance directly, while verified actions can award CAL automatically with a permanent history.</p><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-emerald-100 bg-emerald-50 p-4"><p className="text-[10px] font-black uppercase tracking-wider text-emerald-700">Active Calcitonin pool</p><p className="mt-2 text-2xl font-black text-emerald-900">{totalCalcitonins.toLocaleString()} <span className="text-sm">CAL</span></p></div><div className="rounded-xl border border-slate-100 bg-slate-50 p-4"><p className="text-[10px] font-black uppercase tracking-wider text-slate-500">Members with CAL</p><p className="mt-2 text-2xl font-black text-slate-900">{activeMembers.length}</p></div><div className="rounded-xl border border-amber-100 bg-amber-50 p-4"><p className="text-[10px] font-black uppercase tracking-wider text-amber-700">Current leader</p><p className="mt-2 truncate text-lg font-black text-amber-950">{topMember?.name || '—'}</p></div></div>{message && <p role="status" className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}<section className="mt-6 rounded-2xl border border-slate-100"><div className="border-b border-slate-100 px-5 py-4"><p className="font-black text-slate-900">Automatic Calcitonin rules</p><p className="mt-1 text-xs text-slate-500">Each rule can be switched off without losing its protected history.</p></div><div className="divide-y divide-slate-100">{rules.map((rule) => <div key={rule.rule_key} className="flex flex-wrap items-center gap-4 px-5 py-4"><div className="min-w-52 flex-1"><p className="font-bold text-slate-900">{rule.label}</p><p className="mt-1 text-xs leading-5 text-slate-500">{rule.description}</p></div><input type="number" min="0" max="10000" defaultValue={rule.points} onBlur={(event) => { if (Number(event.target.value) !== Number(rule.points)) void updateRule(rule, { points: Number(event.target.value) }); }} className="w-24 rounded-lg border border-slate-200 px-3 py-2 text-sm font-black text-emerald-700" aria-label={`${rule.label} Calcitonins`} /><span className="text-xs font-bold text-slate-400">CAL</span><button disabled={busy === `rule-${rule.rule_key}`} onClick={() => void updateRule(rule, { enabled: !rule.enabled })} className={`rounded-lg px-3 py-2 text-xs font-black disabled:opacity-60 ${rule.enabled ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{busy === `rule-${rule.rule_key}` ? 'Saving…' : rule.enabled ? 'Enabled' : 'Disabled'}</button></div>)}{!rules.length && <Empty label="Automatic Calcitonin rules are loading." />}</div></section><section className="mt-7 grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]"><form onSubmit={adjust} className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Direct PHANTOM adjustment</p><h4 className="mt-1 text-lg font-black text-slate-900">Add, deduct, or set Calcitonins</h4><select required value={selectedId} onChange={(event) => void loadHistory(event.target.value)} className="mt-4 w-full rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm"><option value="">Choose member</option>{activeMembers.map((member) => <option key={member.id} value={member.id}>{member.member_code} · {member.name} · {Number(member.points || 0).toLocaleString()} CAL</option>)}</select><div className="mt-3 grid grid-cols-2 gap-3"><select value={action} onChange={(event) => setAction(event.target.value as typeof action)} className="rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm font-bold"><option value="add">Add CAL</option><option value="deduct">Deduct CAL</option><option value="set">Set CAL balance</option></select><input required min="0" type="number" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="CAL" className="rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm" /></div><textarea required value={reason} onChange={(event) => setReason(event.target.value)} maxLength={500} placeholder="Reason for this Calcitonin change" className="mt-3 min-h-24 w-full resize-y rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm" /><button disabled={busy === 'adjust'} className="mt-3 w-full rounded-xl bg-emerald-600 py-3 text-xs font-black uppercase tracking-wider text-white disabled:opacity-60">{busy === 'adjust' ? 'Saving…' : 'Save Calcitonin adjustment'}</button></form><div className="rounded-2xl border border-slate-100 p-5"><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Calcitonin history</p><h4 className="mt-1 text-lg font-black text-slate-900">{selectedId ? 'Selected member activity' : 'Choose a member to inspect history'}</h4><div className="mt-4 max-h-80 space-y-2 overflow-y-auto">{history.length ? <RecentItems items={history} label="Calcitonin events" render={(event) => <article key={event.id} className="rounded-xl bg-slate-50 p-3"><div className="flex items-center justify-between gap-3"><strong className={Number(event.points_delta) >= 0 ? 'text-emerald-700' : 'text-red-600'}>{Number(event.points_delta) >= 0 ? '+' : ''}{event.points_delta} CAL</strong><span className="text-xs font-black text-slate-500">Balance {event.balance_after} CAL</span></div><p className="mt-1 text-xs text-slate-700">{event.reason || event.rule_key || event.event_type}</p><p className="mt-1 text-[10px] text-slate-400">{event.changed_by_name || 'Automatic'} · {event.created_at}</p></article>} /> : null}{selectedId && !history.length && <p className="text-sm text-slate-500">No Calcitonin events recorded yet.</p>}</div></div></section></div>;
};

const NotificationAdministration = ({ delegates, members, roles, sentNotifications, onSaved }: { delegates: any[]; members: any[]; roles: any[]; sentNotifications: any[]; onSaved: () => void }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [audience, setAudience] = useState<'all' | 'selected' | 'role'>('all');
  const [selected, setSelected] = useState<number[]>([]);
  const [roleCode, setRoleCode] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editBody, setEditBody] = useState('');
  const delegateMap = new Map(delegates.map((delegate) => [delegate.member_profile_id, Number(delegate.can_send) === 1]));
  const activeMembers = members.filter((member) => member.status === 'active' && member.role_code !== 'phantom');

  const send = async (event: React.FormEvent) => {
    event.preventDefault();
    setMessage(null);
    if (!title.trim() || !body.trim()) { setMessage({ type: 'error', text: 'Add a title and message.' }); return; }
    if (audience === 'selected' && !selected.length) { setMessage({ type: 'error', text: 'Choose at least one active member.' }); return; }
    if (audience === 'role' && !roleCode) { setMessage({ type: 'error', text: 'Choose a responsibility profile.' }); return; }
    setBusy('send');
    try {
      const result = await db.notifications.send({ title, message: body, audience, memberProfileIds: selected, roleCode });
      setMessage({ type: 'success', text: result.message || 'Notification sent.' });
      setTitle(''); setBody(''); setSelected([]); setRoleCode('');
      onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not send this notification.' }); }
    finally { setBusy(null); }
  };

  const toggleDelegate = async (member: any, canSend: boolean) => {
    setBusy(`delegate-${member.id}`); setMessage(null);
    try { await db.phantom.setNotificationDelegate(member.id, canSend); setMessage({ type: 'success', text: `${member.name}'s sender access was updated.` }); onSaved(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update notification access.' }); }
    finally { setBusy(null); }
  };

  const startEditing = (notification: any) => { setEditingId(notification.id); setEditTitle(notification.title); setEditBody(notification.message); setMessage(null); };
  const saveEdit = async (notification: any) => {
    if (!editTitle.trim() || !editBody.trim()) { setMessage({ type: 'error', text: 'Use a title and message before saving.' }); return; }
    setBusy(`edit-${notification.id}`); setMessage(null);
    try {
      await db.notifications.updateSent(notification.id, { title: editTitle, message: editBody });
      setEditingId(null); setMessage({ type: 'success', text: 'Notification updated for every current recipient.' }); onSaved();
    } catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not update this notification.' }); }
    finally { setBusy(null); }
  };
  const deleteSent = async (notification: any) => {
    if (!window.confirm(`Withdraw “${notification.title}” from all recipient inboxes?`)) return;
    setBusy(`delete-${notification.id}`); setMessage(null);
    try { await db.notifications.deleteSent(notification.id); setMessage({ type: 'success', text: 'Notification moved to the Recycle Bin and withdrawn from inboxes.' }); onSaved(); }
    catch (error: any) { setMessage({ type: 'error', text: error?.message || 'Could not withdraw this notification.' }); }
    finally { setBusy(null); }
  };

  return <div>
    <Header eyebrow="Broadcast and delivery" title="Notifications" />
    <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Send an update to all active members, a responsibility profile, or selected members. Sent notices stay manageable: edit their content or move them to the Recycle Bin whenever needed.</p>
    {message && <p role="status" className={`mt-4 rounded-xl px-4 py-3 text-sm font-medium ${message.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-600'}`}>{message.text}</p>}
    <section className="mt-6 grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <form onSubmit={send} className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">PHANTOM broadcast composer</p><input required value={title} onChange={(event) => setTitle(event.target.value)} maxLength={180} placeholder="Notification title" className="mt-4 w-full rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm" /><textarea required value={body} onChange={(event) => setBody(event.target.value)} maxLength={5000} placeholder="Write the update you want members to receive…" className="mt-3 min-h-32 w-full resize-y rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm leading-6" /><select value={audience} onChange={(event) => setAudience(event.target.value as typeof audience)} className="mt-3 w-full rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm font-bold"><option value="all">All active members</option><option value="selected">Selected members</option><option value="role">Responsibility profile</option></select>{audience === 'role' && <select value={roleCode} onChange={(event) => setRoleCode(event.target.value)} className="mt-3 w-full rounded-xl border border-emerald-200 bg-white px-3 py-3 text-sm"><option value="">Choose responsibility profile</option>{roles.filter((role) => role.code !== 'phantom').map((role) => <option key={role.code} value={role.code}>{role.name}</option>)}</select>}{audience === 'selected' && <div className="mt-3 max-h-48 overflow-y-auto rounded-xl border border-emerald-200 bg-white p-2">{activeMembers.map((member) => <label key={member.id} className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-2 text-xs hover:bg-emerald-50"><input type="checkbox" checked={selected.includes(member.id)} onChange={() => setSelected((current) => current.includes(member.id) ? current.filter((id) => id !== member.id) : [...current, member.id])} /><span><strong className="text-slate-800">{member.name}</strong><small className="ml-2 text-slate-500">{member.member_code}</small></span></label>)}</div>}<button disabled={busy === 'send'} className="mt-4 w-full rounded-xl bg-emerald-600 py-3 text-xs font-black uppercase tracking-wider text-white disabled:opacity-60">{busy === 'send' ? 'Sending…' : 'Send notification'}</button></form>
      <div className="rounded-2xl border border-slate-100 p-5"><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Delegated notification team</p><h4 className="mt-1 text-lg font-black text-slate-900">Assign trusted senders</h4><p className="mt-2 text-sm leading-6 text-slate-500">Enabled members receive the same in-app composer in their dashboard. PHANTOM always retains broadcast access.</p><div className="mt-4 max-h-[30rem] space-y-2 overflow-y-auto">{activeMembers.map((member) => { const enabled = delegateMap.get(member.id) || false; return <div key={member.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 px-3 py-3"><span className="min-w-0"><strong className="block truncate text-sm text-slate-800">{member.name}</strong><small className="block truncate text-xs text-slate-500">{member.member_code} · {member.role_name || member.role_code}</small></span><button disabled={busy === `delegate-${member.id}`} onClick={() => void toggleDelegate(member, !enabled)} className={`shrink-0 rounded-lg px-3 py-2 text-xs font-black disabled:opacity-60 ${enabled ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{busy === `delegate-${member.id}` ? 'Saving…' : enabled ? 'Sender enabled' : 'Enable sender'}</button></div>; })}{!activeMembers.length && <Empty label="No active members are available for delegation." />}</div></div>
    </section>
    <section className="mt-7 rounded-2xl border border-slate-100 p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Sent notifications</p><h4 className="mt-1 text-lg font-black text-slate-900">Edit or recycle a sent notice</h4><p className="mt-1 text-sm text-slate-500">The three newest notices appear first. Editing updates all current recipients; recycling removes it from inboxes and keeps it recoverable.</p></div><span className="text-xs font-bold text-slate-400">{sentNotifications.length} active</span></div><div className="mt-4 space-y-3">{sentNotifications.length ? <RecentItems items={sentNotifications} label="sent notifications" render={(notification) => <article key={notification.id} className="rounded-xl border border-slate-100 bg-slate-50 p-4">{editingId === notification.id ? <div><input value={editTitle} onChange={(event) => setEditTitle(event.target.value)} maxLength={180} className="w-full rounded-lg border border-emerald-200 bg-white px-3 py-2 text-sm font-black text-slate-800" /><textarea value={editBody} onChange={(event) => setEditBody(event.target.value)} maxLength={5000} className="mt-3 min-h-28 w-full resize-y rounded-lg border border-emerald-200 bg-white px-3 py-2 text-sm leading-6 text-slate-700" /><div className="mt-3 flex flex-wrap gap-2"><button disabled={busy === `edit-${notification.id}`} onClick={() => void saveEdit(notification)} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-black text-white disabled:opacity-60">{busy === `edit-${notification.id}` ? 'Saving…' : 'Save changes'}</button><button onClick={() => setEditingId(null)} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-600">Cancel</button></div></div> : <div><div className="flex items-start justify-between gap-4"><div className="min-w-0"><p className="font-black text-slate-900">{notification.title}</p><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-600">{notification.message}</p><p className="mt-3 text-[10px] font-black uppercase tracking-wider text-slate-400">{notification.audience_label || notification.audience_type} · {notification.recipient_count} recipients · {notification.read_count} read · {notification.sent_at}</p></div><div className="flex shrink-0 gap-1"><button onClick={() => startEditing(notification)} title="Edit sent notification" className="rounded-lg p-2 text-emerald-700 transition hover:bg-emerald-100"><Edit3 className="h-4 w-4" /></button><button disabled={busy === `delete-${notification.id}`} onClick={() => void deleteSent(notification)} title="Move sent notification to Recycle Bin" className="rounded-lg p-2 text-red-600 transition hover:bg-red-100 disabled:opacity-60"><Trash2 className="h-4 w-4" /></button></div></div></div>}</article>} /> : <Empty label="No active notifications have been sent yet." />}</div></section>
  </div>;
};

const Settings = ({ settings, sections, onSaved }: { settings: any[]; sections: any[]; onSaved: () => void }) => { const [key, setKey] = useState(''); const [value, setValue] = useState(''); const [slug, setSlug] = useState(''); const [title, setTitle] = useState(''); return <div><Header eyebrow="System settings" title="PHANTOM-only settings" /><div className="mt-5 rounded-2xl border border-slate-100 p-5"><div className="grid gap-3 sm:grid-cols-2"><input value={key} onChange={(event) => setKey(event.target.value)} placeholder="Setting key" className="rounded-xl border border-slate-200 px-4 py-3 text-sm" /><input value={value} onChange={(event) => setValue(event.target.value)} placeholder="Setting value" className="rounded-xl border border-slate-200 px-4 py-3 text-sm" /></div><button onClick={async () => { if (key && value) { await db.phantom.saveSetting(key, value); setKey(''); setValue(''); onSaved(); } }} className="mt-3 rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase text-white">Save setting</button></div><div className="mt-7 border-t border-slate-100 pt-7"><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Configurable Vault structure</p><h4 className="mt-1 text-lg font-black text-slate-900">Vault sections</h4><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><input value={slug} onChange={(event) => setSlug(event.target.value)} placeholder="section-slug" className="rounded-xl border border-slate-200 px-4 py-3 text-sm" /><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Section title" className="rounded-xl border border-slate-200 px-4 py-3 text-sm" /><button onClick={async () => { if (slug && title) { await db.phantom.createVaultSection({ slug, title }); setSlug(''); setTitle(''); onSaved(); } }} className="rounded-xl bg-emerald-600 px-4 py-3 text-xs font-black uppercase text-white">Add</button></div><div className="mt-4 space-y-2">{sections.map((section) => <div key={section.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-100 px-4 py-3"><div><p className="font-bold text-slate-800">{section.title}</p><p className="text-xs text-slate-500">{section.slug}{section.is_sensitive ? ' · restricted' : ''}</p></div>{!section.is_archived && <button onClick={async () => { if (window.confirm(`Archive ${section.title}? Existing records stay preserved.`)) { await db.phantom.updateVaultSection(section.id, { archive: true }); onSaved(); } }} className="mini-button text-red-600">Archive</button>}{section.is_archived && <button onClick={async () => { await db.phantom.updateVaultSection(section.id, { archive: false }); onSaved(); }} className="mini-button text-emerald-700">Unarchive</button>}</div>)}</div></div><div className="mt-5 space-y-2">{settings.map((setting) => <div key={setting.setting_key} className="rounded-xl border border-slate-100 px-4 py-3"><p className="text-xs font-black text-slate-800">{setting.setting_key}</p><p className="mt-1 break-all text-sm text-slate-500">{setting.setting_value}</p></div>)}</div></div> };

const CreateMemberModal = ({ application, roles, onClose, onCreated }: { application: any; roles: any[]; onClose: () => void; onCreated: () => void }) => {
  const [form, setForm] = useState({ name: application?.name || '', email: application?.email || '', phone: application?.phone || '', roleCode: 'member', codenamePath: 'member', foundingCodenameId: '', reviewNote: application?.review_note || '' });
  const [foundingCodenames, setFoundingCodenames] = useState<any[]>([]);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    db.phantom.codenames().then((data) => setFoundingCodenames((data.codenames || []).filter((item: any) => item.pool === 'founding' && item.status === 'available'))).catch(() => setFoundingCodenames([]));
  }, []);

  const setPath = (codenamePath: string) => setForm((current) => ({
    ...current,
    codenamePath,
    roleCode: codenamePath === 'custom_founding' ? 'custom' : current.roleCode === 'custom' ? 'member' : current.roleCode,
    foundingCodenameId: codenamePath === 'direct_founding' ? current.foundingCodenameId : '',
  }));

  const copyActivationLink = async () => {
    if (!result?.activationUrl) return;
    try { await navigator.clipboard?.writeText(result.activationUrl); setCopied(true); window.setTimeout(() => setCopied(false), 1800); }
    catch { setError('Could not copy automatically. Select and copy the secure link below.'); }
  };

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    if (form.codenamePath === 'direct_founding' && !form.foundingCodenameId) {
      setError('Choose an available founding codename for direct assignment.');
      return;
    }
    setSubmitting(true);
    try {
      const payload = { ...form, foundingCodenameId: form.foundingCodenameId ? Number(form.foundingCodenameId) : undefined };
      const response = application ? await db.phantom.approveAndInviteApplication(application.id, payload) : await db.phantom.createMember(payload);
      setResult({ ...response.data, message: response.message });
    } catch (err: any) { setError(err?.message || 'Could not create the secure member invitation.'); }
    finally { setSubmitting(false); }
  };

  const responsibilityRoles = roles.filter((role) => !['phantom', 'nexus', 'ghost', 'falcon', 'quantum', 'matrix'].includes(role.code));
  const expiry = result?.activationExpiresAt ? new Date(result.activationExpiresAt).toLocaleString(undefined, { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
  return <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">PHANTOM · Membership invitation</p><h3 className="mt-1 text-2xl font-black text-slate-900">{application ? 'Approve & create secure invitation' : 'Create member & secure invitation'}</h3><p className="mt-2 text-sm leading-6 text-slate-500">One confirmation creates the pending member, permanent member ID, and one-time password-setup invitation. The applicant creates their own password; PHANTOM never sees it.</p></div><button onClick={onClose} className="rounded-full p-2 text-slate-400 hover:bg-slate-100" aria-label="Close"><X className="h-5 w-5" /></button></div>{result ? <div className="mt-6"><div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><Check className="h-6 w-6 text-emerald-600" /><h4 className="mt-3 font-black text-emerald-900">Invitation ready for {result.memberCode}</h4><p className="mt-2 text-sm leading-6 text-emerald-800">{result.activationEmailSent ? 'The activation email was sent. You can also copy the link below as a secure fallback.' : 'Email delivery is not configured or did not complete. Copy this link and send it privately to the applicant.'}</p><div className="mt-4 grid gap-3 rounded-xl border border-emerald-100 bg-white p-4 sm:grid-cols-2"><span><small className="block text-[10px] font-black uppercase tracking-wider text-slate-400">Password setup expires</small><strong className="mt-1 block text-sm text-slate-800">{expiry}</strong></span><span><small className="block text-[10px] font-black uppercase tracking-wider text-slate-400">Identity path</small><strong className="mt-1 block text-sm text-slate-800">{result.codenamePath === 'direct_founding' ? 'Direct Founding assignment' : result.codenamePath === 'custom_founding' ? 'Custom Founding ballot' : 'Member ballot'}</strong></span></div><textarea readOnly value={result.activationUrl || ''} aria-label="Secure password-setup link" className="mt-4 h-24 w-full rounded-xl border border-emerald-200 bg-white p-3 text-xs text-slate-700" /><button onClick={() => void copyActivationLink()} className="mt-3 w-full rounded-xl border border-emerald-200 bg-white py-3 text-xs font-black uppercase tracking-wider text-emerald-700 hover:bg-emerald-100">{copied ? 'Copied secure link' : 'Copy secure password-setup link'}</button><p className="mt-3 text-xs leading-5 text-emerald-800">This raw link is shown only now. If it expires or is lost, use the awaiting-activation member’s key button to generate a replacement; the prior unused link becomes invalid.</p></div><button onClick={onCreated} className="mt-4 w-full rounded-xl bg-emerald-600 py-3 text-sm font-black text-white">Done</button></div> : <form onSubmit={submit} className="mt-6 space-y-3">{application && <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4 text-sm text-emerald-900"><p className="font-black">Applicant: {application.name}</p><p className="mt-1 text-xs text-emerald-800">Review the details, choose the member’s starting path, then approve once to issue their password-setup invitation.</p></div>}<input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Full name" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm" /><input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="Email" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm" /><input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="Phone" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm" /><label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Responsibility profile<select value={form.roleCode} onChange={(event) => { const roleCode = event.target.value; setForm({ ...form, roleCode, codenamePath: roleCode === 'custom' ? 'custom_founding' : form.codenamePath === 'custom_founding' ? 'member' : form.codenamePath }); }} className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm">{responsibilityRoles.map((role) => <option key={role.id} value={role.code}>{role.name}</option>)}</select></label><fieldset className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4"><legend className="px-1 text-[10px] font-black uppercase tracking-widest text-emerald-700">Codename path</legend><label className="mt-2 flex cursor-pointer gap-3 text-sm text-slate-700"><input type="radio" checked={form.codenamePath === 'member'} onChange={() => setPath('member')} /><span><strong className="block">Member Ballot</strong><small className="block text-slate-500">The user chooses from PHANTOM’s separate Member Codename Pool.</small></span></label><label className="mt-3 flex cursor-pointer gap-3 text-sm text-slate-700"><input type="radio" checked={form.codenamePath === 'custom_founding'} onChange={() => setPath('custom_founding')} /><span><strong className="block">Custom Founding Ballot</strong><small className="block text-slate-500">This user sees only the canonical founding identities that are still unclaimed. Taken identities never appear.</small></span></label><label className="mt-3 flex cursor-pointer gap-3 text-sm text-slate-700"><input type="radio" checked={form.codenamePath === 'direct_founding'} onChange={() => setPath('direct_founding')} /><span><strong className="block">Direct Founding Assignment</strong><small className="block text-slate-500">PHANTOM assigns one founding codename now. No ballot is shown.</small></span></label>{form.codenamePath === 'direct_founding' && <select required value={form.foundingCodenameId} onChange={(event) => setForm({ ...form, foundingCodenameId: event.target.value })} className="mt-4 w-full rounded-xl border border-emerald-200 bg-white px-4 py-3 text-sm font-bold text-emerald-800"><option value="">Choose available founding codename</option>{foundingCodenames.map((codename) => <option key={codename.id} value={codename.id}>{codename.display_name}</option>)}</select>}</fieldset>{application && <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">PHANTOM review note<textarea value={form.reviewNote} onChange={(event) => setForm({ ...form, reviewNote: event.target.value })} maxLength={2000} placeholder="Optional private approval note" className="mt-2 min-h-24 w-full resize-y rounded-xl border border-slate-200 p-3 text-sm normal-case tracking-normal" /></label>}{error && <p className="rounded-xl bg-red-50 px-4 py-3 text-sm font-medium text-red-600">{error}</p>}<button disabled={submitting} className="w-full rounded-xl bg-emerald-600 py-3.5 text-sm font-black text-white disabled:opacity-60">{submitting ? 'Creating secure invitation…' : application ? 'Approve & create secure invitation' : 'Create member & invitation'}</button></form>}</div></div>;
};

const ActivationInviteDialog = ({ invitation, onClose }: { invitation: any; onClose: () => void }) => {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try { await navigator.clipboard?.writeText(invitation.activationUrl || ''); setCopied(true); window.setTimeout(() => setCopied(false), 1800); }
    catch { /* The readonly textarea remains a safe manual-copy fallback. */ }
  };
  const expiry = invitation.activationExpiresAt ? new Date(invitation.activationExpiresAt).toLocaleString(undefined, { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
  return <div className="fixed inset-0 z-[125] flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm"><div className="w-full max-w-xl rounded-3xl bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-widest text-sky-600">Replacement invitation</p><h3 className="mt-1 text-2xl font-black text-slate-900">Secure password-setup link ready</h3><p className="mt-2 text-sm leading-6 text-slate-500">The earlier unused activation link was invalidated. Send this replacement only to the member.</p></div><button onClick={onClose} className="rounded-full p-2 text-slate-400 hover:bg-slate-100" aria-label="Close"><X className="h-5 w-5" /></button></div><div className="mt-5 rounded-2xl border border-sky-100 bg-sky-50 p-4"><p className="font-black text-sky-950">{invitation.memberCode}</p><p className="mt-1 text-xs font-bold text-sky-800">Expires: {expiry}</p><p className="mt-2 text-sm text-sky-900">{invitation.activationEmailSent ? 'The replacement was emailed successfully.' : 'Email delivery needs manual fallback. Copy and send the link securely.'}</p><textarea readOnly value={invitation.activationUrl || ''} aria-label="Replacement secure password-setup link" className="mt-4 h-24 w-full rounded-xl border border-sky-200 bg-white p-3 text-xs text-slate-700" /><button onClick={() => void copy()} className="mt-3 w-full rounded-xl border border-sky-200 bg-white py-3 text-xs font-black uppercase tracking-wider text-sky-800 hover:bg-sky-100">{copied ? 'Copied secure link' : 'Copy secure password-setup link'}</button></div></div></div>;
};

const MemberHistory = ({ member, onClose }: { member: any; onClose: () => void }) => {
  const [data, setData] = useState<any>(null);
  useEffect(() => { db.phantom.memberHistory(member.id).then(setData).catch(() => setData({ error: 'Could not load history.' })); }, [member.id]);
  const roles = data?.roles || [];
  const activity = data?.activity || [];

  return <div className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/50 p-4"><div className="max-h-[85vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-widest text-emerald-600">Member history</p><h3 className="mt-1 text-2xl font-black text-slate-900">{member.name}</h3><p className="mt-1 text-xs text-slate-500">Three recent entries are shown first.</p></div><button onClick={onClose} className="rounded-full p-2 text-slate-400 hover:bg-slate-100"><X className="h-5 w-5" /></button></div>{data?.error ? <p className="mt-5 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-600">{data.error}</p> : <><section className="mt-6"><h4 className="font-black text-slate-800">Role history</h4><div className="mt-3 space-y-2">{roles.length ? <RecentItems items={roles} label="role changes" render={(item) => <div key={item.id} className="rounded-xl bg-slate-50 p-3 text-sm text-slate-600">{item.previous_role || '—'} → <strong>{item.new_role}</strong> · {item.changed_at}</div>} /> : <p className="text-sm text-slate-500">No role changes recorded yet.</p>}</div></section><section className="mt-6"><h4 className="font-black text-slate-800">Activity</h4><div className="mt-3 space-y-2">{activity.length ? <RecentItems items={activity} label="activity entries" render={(item) => <div key={item.id} className="rounded-xl bg-slate-50 p-3 text-sm text-slate-600">{String(item.action || '').replace(/\./g, ' ')} · {item.created_at}</div>} /> : <p className="text-sm text-slate-500">No activity recorded yet.</p>}</div></section></>}</div></div>;
};

const Header = ({ eyebrow, title }: { eyebrow: string; title: string }) => <div><p className="text-[10px] font-black uppercase tracking-[0.18em] text-emerald-600">{eyebrow}</p><h3 className="mt-1 text-2xl font-black text-slate-900">{title}</h3></div>;
const Empty = ({ label }: { label: string }) => <div className="rounded-2xl border border-dashed border-slate-200 p-8 text-center text-sm text-slate-500">{label}</div>;
const Status = ({ status }: { status: string }) => <span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-black uppercase tracking-wider ${status === 'active' || status === 'available' || status === 'claimed' ? 'bg-emerald-50 text-emerald-700' : status === 'pending' || status === 'pending_activation' || status === 'reserved' ? 'bg-amber-50 text-amber-700' : status === 'locked' ? 'bg-red-50 text-red-600' : 'bg-slate-100 text-slate-500'}`}>{status?.replace(/_/g, ' ')}</span>;
const SaveIcon = () => <Check className="h-4 w-4" />;
